-- SORA Executive Workspace — schema V1 (MariaDB 10.6+ / MySQL 8.0.16+)
-- Ported from supabase/migrations/20261012000001..3 (PostgreSQL).
-- Rules:
--   * Every timestamp is stored in UTC as DATETIME(3). The application sets all values; no DB defaults on time columns.
--   * Ids are CHAR(36) UUID strings generated by the application.
--   * Business rules that were PostgreSQL triggers (version stamp, created_by/updated_by, audit, completed_at,
--     follow-up propagation) live in the application layer (Data/Repo.cs). Hosted MariaDB often forbids
--     CREATE TRIGGER under binary logging, so nothing here depends on triggers.
--   * CHECK constraints are kept as a second line of defence and are portable to MySQL 8 (names are table-prefixed,
--     and no CHECK touches a column that has an ON DELETE SET NULL / CASCADE action).
-- Statements are separated by a line containing only "-- GO" (see Data/Migrator.cs).

CREATE TABLE IF NOT EXISTS `profiles` (
  `id`            CHAR(36)     NOT NULL,
  `email`         VARCHAR(190) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `display_name`  VARCHAR(120) NOT NULL,
  `role`          VARCHAR(16)  NOT NULL,
  `active`        TINYINT(1)   NOT NULL DEFAULT 1,
  `last_login_at` DATETIME(3)  NULL,
  `created_at`    DATETIME(3)  NOT NULL,
  `updated_at`    DATETIME(3)  NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_profiles_email` (`email`),
  CONSTRAINT `chk_profiles_role` CHECK (`role` IN ('director','secretary'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `people` (
  `id`           CHAR(36)     NOT NULL,
  `full_name`    VARCHAR(200) NOT NULL,
  `department`   VARCHAR(200) NULL,
  `position`     VARCHAR(200) NULL,
  `contact_note` TEXT         NULL,
  `active`       TINYINT(1)   NOT NULL DEFAULT 1,
  `created_at`   DATETIME(3)  NOT NULL,
  `updated_at`   DATETIME(3)  NOT NULL,
  `created_by`   CHAR(36)     NULL,
  `updated_by`   CHAR(36)     NULL,
  `version`      INT          NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_people_name` (`full_name`),
  CONSTRAINT `fk_people_created_by` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_people_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_people_name` CHECK (CHAR_LENGTH(TRIM(`full_name`)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `categories` (
  `code`  CHAR(1)      NOT NULL,
  `name`  VARCHAR(100) NOT NULL,
  `color` VARCHAR(16)  NOT NULL,
  PRIMARY KEY (`code`),
  CONSTRAINT `chk_categories_code` CHECK (`code` IN ('A','B','C','D','E','F'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `goals` (
  `id`            CHAR(36)     NOT NULL,
  `title`         VARCHAR(500) NOT NULL,
  `description`   TEXT         NULL,
  `category_code` CHAR(1)      NULL,
  `period_type`   VARCHAR(16)  NOT NULL DEFAULT 'month',
  `start_date`    DATE         NULL,
  `due_date`      DATE         NULL,
  `progress`      DECIMAL(5,2) NOT NULL DEFAULT 0,
  `status`        VARCHAR(16)  NOT NULL DEFAULT 'active',
  `source`        VARCHAR(16)  NOT NULL DEFAULT 'user',
  `created_at`    DATETIME(3)  NOT NULL,
  `updated_at`    DATETIME(3)  NOT NULL,
  `created_by`    CHAR(36)     NULL,
  `updated_by`    CHAR(36)     NULL,
  `version`       INT          NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_goals_status_due` (`status`, `due_date`),
  CONSTRAINT `fk_goals_category`   FOREIGN KEY (`category_code`) REFERENCES `categories` (`code`),
  CONSTRAINT `fk_goals_created_by` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_goals_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_goals_title`    CHECK (CHAR_LENGTH(TRIM(`title`)) > 0),
  CONSTRAINT `chk_goals_period`   CHECK (`period_type` IN ('quarter','month','week')),
  CONSTRAINT `chk_goals_progress` CHECK (`progress` BETWEEN 0 AND 100),
  CONSTRAINT `chk_goals_status`   CHECK (`status` IN ('active','achieved','missed','paused','cancelled')),
  CONSTRAINT `chk_goals_source`   CHECK (`source` IN ('user','demo'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `tasks` (
  `id`                  CHAR(36)     NOT NULL,
  `title`               VARCHAR(500) NOT NULL,
  `description`         TEXT         NULL,
  `category_code`       CHAR(1)      NULL,
  `task_type`           VARCHAR(16)  NOT NULL DEFAULT 'self',
  `priority`            VARCHAR(16)  NOT NULL DEFAULT 'normal',
  `status`              VARCHAR(16)  NOT NULL DEFAULT 'todo',
  `needs_decision`      TINYINT(1)   NOT NULL DEFAULT 0,
  `due_at`              DATETIME(3)  NULL,
  `next_follow_up_at`   DATETIME(3)  NULL,
  `estimated_minutes`   INT          NULL,
  `next_action`         TEXT         NULL,
  `expected_result`     TEXT         NULL,
  `completion_result`   TEXT         NULL,
  `completed_at`        DATETIME(3)  NULL,
  `assignee_profile_id` CHAR(36)     NULL,
  `assignee_person_id`  CHAR(36)     NULL,
  `watcher_profile_id`  CHAR(36)     NULL,
  `goal_id`             CHAR(36)     NULL,
  `source`              VARCHAR(16)  NOT NULL DEFAULT 'user',
  `notes`               TEXT         NULL,
  `created_at`          DATETIME(3)  NOT NULL,
  `updated_at`          DATETIME(3)  NOT NULL,
  `created_by`          CHAR(36)     NULL,
  `updated_by`          CHAR(36)     NULL,
  `version`             INT          NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_tasks_status_due` (`status`, `due_at`),
  KEY `ix_tasks_follow_up`  (`next_follow_up_at`),
  KEY `ix_tasks_category`   (`category_code`),
  KEY `ix_tasks_goal`       (`goal_id`),
  CONSTRAINT `fk_tasks_category`  FOREIGN KEY (`category_code`)       REFERENCES `categories` (`code`),
  CONSTRAINT `fk_tasks_a_profile` FOREIGN KEY (`assignee_profile_id`) REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_tasks_a_person`  FOREIGN KEY (`assignee_person_id`)  REFERENCES `people` (`id`),
  CONSTRAINT `fk_tasks_watcher`   FOREIGN KEY (`watcher_profile_id`)  REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_tasks_goal`      FOREIGN KEY (`goal_id`)             REFERENCES `goals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tasks_created_by` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_tasks_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_tasks_title`    CHECK (CHAR_LENGTH(TRIM(`title`)) > 0),
  CONSTRAINT `chk_tasks_type`     CHECK (`task_type` IN ('self','delegated')),
  CONSTRAINT `chk_tasks_priority` CHECK (`priority` IN ('urgent','high','normal','low')),
  CONSTRAINT `chk_tasks_status`   CHECK (`status` IN ('todo','doing','waiting','paused','done','cancelled')),
  CONSTRAINT `chk_tasks_estimate` CHECK (`estimated_minutes` IS NULL OR `estimated_minutes` BETWEEN 5 AND 6000),
  CONSTRAINT `chk_tasks_source`   CHECK (`source` IN ('user','quick_capture','demo')),
  -- only one of the two assignee kinds; both empty is allowed (quick capture)
  CONSTRAINT `chk_tasks_one_assignee` CHECK (`assignee_profile_id` IS NULL OR `assignee_person_id` IS NULL),
  -- DONE requires a recorded result (enforced here, not only in the UI)
  CONSTRAINT `chk_tasks_done_requires_result`
    CHECK (`status` <> 'done' OR CHAR_LENGTH(TRIM(COALESCE(`completion_result`, ''))) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `task_updates` (
  `id`                CHAR(36)    NOT NULL,
  `task_id`           CHAR(36)    NOT NULL,
  `note`              TEXT        NOT NULL,
  `progress_percent`  INT         NULL,
  `channel`           VARCHAR(16) NULL,
  `next_follow_up_at` DATETIME(3) NULL,
  `author_id`         CHAR(36)    NULL,
  `created_at`        DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_task_updates_task` (`task_id`, `created_at`),
  KEY `ix_task_updates_created` (`created_at`),
  CONSTRAINT `fk_task_updates_task`   FOREIGN KEY (`task_id`)   REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_task_updates_author` FOREIGN KEY (`author_id`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_task_updates_note`     CHECK (CHAR_LENGTH(TRIM(`note`)) > 0),
  CONSTRAINT `chk_task_updates_progress` CHECK (`progress_percent` IS NULL OR `progress_percent` BETWEEN 0 AND 100),
  CONSTRAINT `chk_task_updates_channel`  CHECK (`channel` IS NULL OR `channel` IN ('zalo','phone','email','in_person','other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `task_links` (
  `id`         CHAR(36)      NOT NULL,
  `task_id`    CHAR(36)      NOT NULL,
  `label`      VARCHAR(300)  NULL,
  `url`        VARCHAR(2000) NOT NULL,
  `created_at` DATETIME(3)   NOT NULL,
  `created_by` CHAR(36)      NULL,
  PRIMARY KEY (`id`),
  KEY `ix_task_links_task` (`task_id`),
  CONSTRAINT `fk_task_links_task`    FOREIGN KEY (`task_id`)    REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_task_links_creator` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_task_links_url` CHECK (`url` REGEXP '^https?://')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `calendar_events` (
  `id`                   CHAR(36)     NOT NULL,
  `title`                VARCHAR(500) NOT NULL,
  `start_at`             DATETIME(3)  NOT NULL,
  `end_at`               DATETIME(3)  NOT NULL,
  `event_type`           VARCHAR(16)  NOT NULL DEFAULT 'flexible',
  `category_code`        CHAR(1)      NULL,
  `task_id`              CHAR(36)     NULL,
  `locked`               TINYINT(1)   NOT NULL DEFAULT 0,
  `recurrence_rule`      VARCHAR(500) NULL,
  `recurrence_parent_id` CHAR(36)     NULL,
  `timezone`             VARCHAR(64)  NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  `status`               VARCHAR(16)  NOT NULL DEFAULT 'confirmed',
  `notes`                TEXT         NULL,
  `source`               VARCHAR(16)  NOT NULL DEFAULT 'user',
  `created_at`           DATETIME(3)  NOT NULL,
  `updated_at`           DATETIME(3)  NOT NULL,
  `created_by`           CHAR(36)     NULL,
  `updated_by`           CHAR(36)     NULL,
  `version`              INT          NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_calendar_events_range` (`start_at`, `end_at`),
  KEY `ix_calendar_events_task`  (`task_id`),
  CONSTRAINT `fk_calendar_events_category` FOREIGN KEY (`category_code`)        REFERENCES `categories` (`code`),
  CONSTRAINT `fk_calendar_events_task`     FOREIGN KEY (`task_id`)              REFERENCES `tasks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_calendar_events_parent`   FOREIGN KEY (`recurrence_parent_id`) REFERENCES `calendar_events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_calendar_events_created_by` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `fk_calendar_events_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_calendar_events_title`  CHECK (CHAR_LENGTH(TRIM(`title`)) > 0),
  CONSTRAINT `chk_calendar_events_time`   CHECK (`end_at` > `start_at`),
  CONSTRAINT `chk_calendar_events_type`   CHECK (`event_type` IN ('fixed','focus','flexible','urgent','buffer')),
  CONSTRAINT `chk_calendar_events_status` CHECK (`status` IN ('confirmed','tentative','cancelled','done')),
  CONSTRAINT `chk_calendar_events_source` CHECK (`source` IN ('user','scheduler','demo'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `recurrence_exceptions` (
  `id`                   CHAR(36)    NOT NULL,
  `parent_event_id`      CHAR(36)    NOT NULL,
  `occurrence_start_at`  DATETIME(3) NOT NULL,
  `action`               VARCHAR(16) NOT NULL,
  `replacement_event_id` CHAR(36)    NULL,
  `created_at`           DATETIME(3) NOT NULL,
  `created_by`           CHAR(36)    NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recurrence_exceptions` (`parent_event_id`, `occurrence_start_at`),
  CONSTRAINT `fk_recurrence_exceptions_parent`  FOREIGN KEY (`parent_event_id`)      REFERENCES `calendar_events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_recurrence_exceptions_repl`    FOREIGN KEY (`replacement_event_id`) REFERENCES `calendar_events` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_recurrence_exceptions_creator` FOREIGN KEY (`created_by`)           REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_recurrence_exceptions_action` CHECK (`action` IN ('skip','replace'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `weekly_priorities` (
  `id`         CHAR(36)    NOT NULL,
  `week_start` DATE        NOT NULL,
  `task_id`    CHAR(36)    NOT NULL,
  `rank`       INT         NOT NULL,
  `chosen_by`  CHAR(36)    NULL,
  `created_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_weekly_priorities_rank` (`week_start`, `rank`),
  UNIQUE KEY `uq_weekly_priorities_task` (`week_start`, `task_id`),
  CONSTRAINT `fk_weekly_priorities_task`    FOREIGN KEY (`task_id`)   REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_weekly_priorities_chooser` FOREIGN KEY (`chosen_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `chk_weekly_priorities_rank` CHECK (`rank` BETWEEN 1 AND 3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `notifications` (
  `id`                CHAR(36)     NOT NULL,
  `target_profile_id` CHAR(36)     NOT NULL,
  `kind`              VARCHAR(32)  NOT NULL,
  `entity_type`       VARCHAR(16)  NOT NULL,
  `entity_id`         CHAR(36)     NOT NULL,
  `scheduled_at`      DATETIME(3)  NOT NULL,
  `read_at`           DATETIME(3)  NULL,
  `resolved_at`       DATETIME(3)  NULL,
  `dedupe_key`        VARCHAR(191) NOT NULL,
  `created_at`        DATETIME(3)  NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notifications_dedupe` (`dedupe_key`),
  KEY `ix_notifications_target` (`target_profile_id`, `read_at`),
  KEY `ix_notifications_open`   (`target_profile_id`, `resolved_at`),
  CONSTRAINT `fk_notifications_target` FOREIGN KEY (`target_profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_notifications_kind` CHECK (`kind` IN ('overdue','follow_up_due','due_soon_1','due_soon_3','due_soon_7',
    'decision_needed','event_starting','missing_owner','missing_next_action','strategy_gap')),
  CONSTRAINT `chk_notifications_entity` CHECK (`entity_type` IN ('task','calendar_event','goal'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `audit_logs` (
  `id`          BIGINT      NOT NULL AUTO_INCREMENT,
  `table_name`  VARCHAR(64) NOT NULL,
  `record_id`   CHAR(36)    NULL,
  `action`      VARCHAR(8)  NOT NULL,
  `before_data` JSON        NULL,
  `after_data`  JSON        NULL,
  `actor_id`    CHAR(36)    NULL,
  `created_at`  DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_audit_logs_record`  (`table_name`, `record_id`, `created_at`),
  KEY `ix_audit_logs_created` (`created_at`),
  KEY `ix_audit_logs_actor`   (`actor_id`),
  CONSTRAINT `chk_audit_logs_action` CHECK (`action` IN ('INSERT','UPDATE','DELETE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

CREATE TABLE IF NOT EXISTS `settings` (
  `key`        VARCHAR(64) NOT NULL,
  `value`      JSON        NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  `updated_by` CHAR(36)    NULL,
  PRIMARY KEY (`key`),
  CONSTRAINT `fk_settings_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- GO

